// A bare "--" is not an option: normalizing never takes positional file
// arguments, so it is reported like any other unknown argument. Any problem
// is a usage error that must end the process with status 2 before any log is
// read.
func parseNormalizeArgs(args []string) (normalizeConfig, error) {
	var cfg normalizeConfig
	sourceCIDRSet := false
	for _, arg := range args {
		switch {
		case arg == "--source-cidr":
			return cfg, errors.New(`--source-cidr requires a value: use --source-cidr=IPV4/PREFIX`)
		case strings.HasPrefix(arg, "--source-cidr="):
			value := strings.TrimPrefix(arg, "--source-cidr=")
			if value == "" {
				return cfg, errors.New(`--source-cidr requires a non-empty value: dotted-decimal IPv4 address plus a /0-/32 prefix`)
			}
			if sourceCIDRSet {
				return cfg, errors.New("--source-cidr may be specified only once")
			}
			cfg.sourceCIDR = value
			sourceCIDRSet = true
		default:
			return cfg, fmt.Errorf("unknown normalize argument %q", arg)
		}
	}
	return cfg, nil
