		t.Fatalf("/0 must keep exactly the three IPv4 sources, got %#v", all)
	}
	for i, want := range []string{"0.0.0.0", "255.255.255.255", "10.20.30.40"} {
		if got := eventOf(t, all[i])["source_ip"]; got != want {
