		t.Fatalf("2 in-net successes plus 4 failures = 6 records, got %#v", results)
	}
	if results[0]["line"] != float64(1) || results[0]["ok"] != true {
		t.Fatalf("in-net line 1 must be kept: %#v", results[0])
